mapper.update:
 	update RSK_VALTBL_ASSET_SUB set
		FINPROD_ID = #{finprodId, jdbcType=VARCHAR}
	where
		PTL_ID = #{ptlId}
		 and (SUB_CODE = #{subCode}


	 		OR SUB_CODE like concat_ws('%',substr(#{subCode},8))
		 )
		and FINPROD_ID is null

mapper.select:
 	SELECT
		count( 1 ) 
	FROM
		RSK_VALTBL_ASSET_SUB
		where PTL_ID = #{ptlId}
		and SUB_CODE = #{subCode}
		and FINPROD_ID is not  null

		and FINPROD_ID != #{finprodId}

mapper.update:
 	update RSK_VALTBL_ASSET_SUB set
		FINPROD_ID = #{finprodId, jdbcType=VARCHAR}
	where
		PTL_ID = #{ptlId}
		and (SUB_CODE = #{subCode} OR SUB_NAME in (SELECT SUB_NAME FROM RSK_VALTBL_ASSET_SUB WHERE SUB_CODE = #{subCode} AND PTL_ID = #{ptlId}))
		and FINPROD_ID is not null

		and FINPROD_ID != #{finprodId}

mapper.select:
SELECT ASSET_CODE as id, /**行内资产负债编码 **/ ifnull(ASSET_NAME,ASSET_CODE) as text /**资产名称**/ FROM chb_asset_info /**资产要素表**/ WHERE status in ('E', 'M')
AND (ASSET_CODE LIKE concat(concat('%', #{search}),'%') OR ASSET_NAME LIKE concat(concat('%', #{search}),'%'))
AND ASSET_CODE = #{initValue}
